style.css:
@-moz-document domain("chat.openai.com") {
/* Arka Plan */
    body {
        background-image: url('https://static0.gamerantimages.com/wordpress/wp-content/uploads/2025/02/bornfree-1.jpg') !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        color: #fff !important;
        font-family: Arial, sans-serif !important;
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 15px #ff0000 !important;
    }

    /* Butonlar için Neon Efekti */
    button, .button {
        background-color: transparent !important; 
        color: #ff0000 !important;
        border: 2px solid #ff0000 !important;
        border-radius: 5px !important;
        padding: 10px 20px !important;
        font-size: 16px !important;
        font-weight: bold !important;
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 15px #ff0000 !important;
        box-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000, 0 0 30px #ff0000 !important;
        transition: all 0.3s ease-in-out !important;
    }

    button:hover, .button:hover {
        background-color: #ff0000 !important;
        color: #fff !important;
        box-shadow: 0 0 20px #ff0000, 0 0 30px #ff0000, 0 0 40px #ff0000 !important;
    }

    /* Yazılar için Neon Efekti */
    h1, h2, h3, h4, h5, h6, p, span, a {
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 15px #ff0000 !important;
    }

    /* Ekranın Etrafında Neon Işık */
    html {
        box-shadow: 0 0 15px 10px #ff0000 !important;
    }

    /* Linkler için Neon Efekti */
    a {
        color: #ff0000 !important;
        text-decoration: none !important;
        text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 15px #ff0000 !important;
        transition: all 0.3s ease-in-out !important;
    }

    a:hover {
        color: #fff !important;
        text-shadow: 0 0 10px #ff0000, 0 0 20px #ff0000, 0 0 30px #ff0000 !important;
    }
}
